from pathlib import Path

TEMPLATE_MARKER = "hard-v3-template-path-30"

def render_report(name):
    # Get template path relative to this file's location, not cwd
    here = Path(__file__).resolve().parent
    template_path = here.parent / "assets" / "templates" / "summary_omega.txt"
    template = template_path.read_text(encoding="utf-8").strip()
    return template.replace("{name}", name)

def preserve_marker():
